      "Dành buổi tối chủ nhật để xem lại tuần qua và chọn ba việc quan trọng nhất cho tuần tới.",
      "Mời một đồng nghiệp đi cà phê để hiểu thêm về công việc của bộ phận họ.",
      "Ghi chép lại những lời góp ý nhận được, rồi chọn một điều để cải thiện trong tháng này.",
      "Chuẩn bị sẵn một đoạn giới thiệu bản thân trong ba mươi giây cho các buổi gặp gỡ.",
      "Hỏi thêm về văn hóa làm việc và giờ giấc thực tế trước khi nhận lời mời.",
      "Thương lượng lại khối lượng công việc với sếp, nêu rõ những gì bạn đang đảm nhận.",
      "Đăng ký tham gia một dự án liên phòng ban để mở rộng quan hệ và học hỏi thêm.",
      "Dành một buổi chiều cập nhật hồ sơ, kể cả khi bạn chưa có ý định nhảy việc.",
      "Tìm hiểu kỹ về người phỏng vấn trên mạng để chuẩn bị câu chuyện phù hợp.",
      "Đặt một quy tắc cho bản thân, như không trả lời tin nhắn công việc sau chín giờ tối.",
